import { gql } from '@apollo/client';

// Fragment imports - these would normally be generated by codegen
export const USER_FRAGMENT = gql`
  fragment User on User {
    id
    email
    username
  }
`;

export const TEAM_FRAGMENT = gql`
  fragment Team on Team {
    id
    leagueId
    name
  }
`;

export const LEAGUE_FRAGMENT = gql`
  fragment League on League {
    id
    name
    description
    numberOfTeams
    draftType
    isPublic
    maxBatters
    maxPitchers
    tradingEnabled
    waiverEnabled
    startDate
  }
`;

export const LEAGUE_MEMBER_FRAGMENT = gql`
  fragment LeagueMember on LeagueMember {
    id
    leagueId
    userId
    isCommissioner
    user {
      ...User
    }
  }
  ${USER_FRAGMENT}
`;

export const CREATE_LEAGUE_AND_TEAMS_MUTATION = gql`
  mutation CreateLeagueAndTeams($input: CreateLeagueAndTeamsInput!) {
    createLeagueAndTeams(input: $input) {
      league {
        ...League
        leagueMembers {
          nodes {
            ...LeagueMember
          }
        }
        teams {
          nodes {
            ...Team
          }
        }
      }
    }
  }
  ${LEAGUE_FRAGMENT}
  ${LEAGUE_MEMBER_FRAGMENT}
  ${TEAM_FRAGMENT}
`;
